import React, { useRef } from "react";
import { interpolate, spring, useCurrentFrame, useVideoConfig, AbsoluteFill } from '../remotionShim';
{/* Start Google Fonts Loader */ }
const useFontLoader = (fonts: string[]) => {
  const stableFonts = React.useMemo(() => {
    const unique = [...new Set(fonts.map(f => f.trim()))].sort();
    return unique;
  }, [fonts.join("|")]); // super light + stable

  React.useEffect(() => {
    const unloaded = stableFonts.filter(
      (font) =>
        !document.querySelector(
          `link[href*="${font.replace(/\s+/g, "+")}"]`
        )
    );

    if (unloaded.length === 0) return;

    const url = `https://fonts.googleapis.com/css2?${unloaded
      .map((font) => `family=${font.replace(/\s+/g, "+")}:wght@400;600;700`)
      .join("&")}&display=swap`;

    const link = document.createElement("link");
    link.rel = "stylesheet";
    link.href = url;

    document.head.appendChild(link);
  }, [stableFonts]);
};
{/* End Google Fonts Loader */ }



export type PieChartHereProps = Record<string, any>;

const getCoordinatesForPercent = (percent: number) => {
  const x = Math.cos(2 * Math.PI * percent);
  const y = Math.sin(2 * Math.PI * percent);
  return [x, y];
};

const PieSlice: React.FC<{
  percent: number;
  color: string;
  startPercent?: number;
}> = ({ percent, color, startPercent = 0 }) => {
  const [startX, startY] = getCoordinatesForPercent(startPercent);
  const [endX, endY] = getCoordinatesForPercent(startPercent + percent);
  const largeArcFlag = percent > 0.5 ? 1 : 0;

  const pathData = [
    `M 0 0`,
    `L ${startX} ${startY}`,
    `A 1 1 0 ${largeArcFlag} 1 ${endX} ${endY}`,
    `L 0 0`,
  ].join(" ");

  return <path d={pathData} fill={color} />;
};

const HandwrittenArrow: React.FC<{ color: string }> = ({ color }) => (
  <svg width="100" height="100" viewBox="0 0 100 100" fill="none" style={{ overflow: "visible" }}>
    {/* Shaft */}
    <path
      d="M90,10 Q50,30 20,80"
      stroke={color}
      strokeWidth="4"
      strokeLinecap="round"
      fill="none"
    />
    {/* Arrowhead */}
    <path
      d="M15,55 L20,80 L45,75"
      stroke={color}
      strokeWidth="4"
      strokeLinecap="round"
      fill="none"
    />
  </svg>
);

const PieChartHere: React.FC<PieChartHereProps> = ({
  backgroundColor = "#ffffff",
  transparentBackground = false,
  durationInSeconds = 5,
  highlightPercentage = 10,
  mainColor = "#e63946",
  highlightColor = "#1d3557",
  arrowColor = "#000000",
  textColor = "#000000",
  textLabel = "you are here",
}) => {
  useFontLoader(["Caveat"]);

  const frame = useCurrentFrame();
  const { fps, width, height } = useVideoConfig();

  // Parser safety for background
  const finalBgColor = transparentBackground ? `${backgroundColor}00` : backgroundColor;

  // Constants for layout
  const radius = Math.min(width, height) * 0.25;
  const diameter = radius * 2;
  const centerX = width / 2;
  const centerY = height / 2;

  // Calculate slice percentages
  const highlightFrac = highlightPercentage / 100;
  const mainFrac = 1 - highlightFrac;

  // Angle for the highlight slice center (to position arrow)
  // We'll rotate the whole chart so the highlight slice is at roughly 2 o'clock for nice visibility
  // By default, 0 degrees is 3 o'clock in SVG math.
  // Let's place the highlight slice centered at -45 degrees (top right).
  const rotationOffset = -45 - (highlightFrac * 360) / 2;

  // Animations
  const entranceSpring = spring({
    frame,
    fps,
    config: { damping: 12, stiffness: 100 },
  });

  const arrowDelay = 15;
  const arrowSpring = spring({
    frame: frame - arrowDelay,
    fps,
    config: { damping: 10, stiffness: 80 },
  });

  const textDelay = 25;
  const textOpacity = interpolate(frame, [textDelay, textDelay + 15], [0, 1], {
    extrapolateLeft: "clamp",
    extrapolateRight: "clamp",
  });

  // Calculate arrow position based on highlight slice center
  // Slice center is at: startPercent + half of slice
  // With our rotation, the visual center of the slice is exactly at -45 degrees (315 deg) relative to screen
  const arrowAngleRad = (Math.PI / 180) * -45;
  const arrowDist = radius * 1.6; // Distance from center
  const arrowX = centerX + Math.cos(arrowAngleRad) * arrowDist;
  const arrowY = centerY + Math.sin(arrowAngleRad) * arrowDist;

  return (
    <AbsoluteFill style={{ backgroundColor: finalBgColor }}>
      {/* Container for the Pie Chart */}
      <div
        style={{
          position: "absolute",
          left: centerX - radius,
          top: centerY - radius,
          width: diameter,
          height: diameter,
          transform: `scale(${entranceSpring}) rotate(${rotationOffset}deg)`,
          transformOrigin: "center center",
        }}
      >
        <svg
          width="100%"
          height="100%"
          viewBox="-1 -1 2 2"
          style={{
            overflow: "visible",
          }}
        >
          {/* Main Slice (Red) - No extra scale group needed due to viewBox */}
          <PieSlice
            percent={mainFrac}
            color={mainColor}
            startPercent={highlightFrac}
          />
          {/* Highlight Slice (Dark Blue/Black) */}
          <PieSlice
            percent={highlightFrac}
            color={highlightColor}
            startPercent={0}
          />
        </svg>
      </div>

      {/* Arrow Container */}
      <div
        style={{
          position: "absolute",
          left: arrowX,
          top: arrowY,
          transform: `translate(-50%, -50%) scale(${arrowSpring})`,
          opacity: Math.min(1, Math.max(0, arrowSpring)), // Clamp opacity
        }}
      >
        {/* Rotate arrow to point towards center roughly */}
        {/* 0deg rotation works because the arrow SVG naturally points South-West (Top-Right to Bottom-Left) */}
        <div style={{ transform: "rotate(0deg)" }}>
           <HandwrittenArrow color={arrowColor} />
        </div>
      </div>

      {/* Text Label */}
      <div
        style={{
          position: "absolute",
          left: arrowX + 60,
          top: arrowY - 60,
          fontFamily: "Caveat",
          fontSize: width * 0.05,
          color: textColor,
          fontWeight: 700,
          opacity: textOpacity,
          transform: `translateY(${interpolate(textOpacity, [0, 1], [10, 0])}px)`,
          whiteSpace: "nowrap",
        }}
      >
        {textLabel}
      </div>
    </AbsoluteFill>
  );
};

export default PieChartHere;